// About hero: 3D far-field radiation pattern (dipole → patch broadside → endfire)
// with a gain heat-map, a glowing wireframe cage, energy particles streaming out
// along each direction (brightness ∝ gain), and expanding far-field shells.
import { threeScene, THREE } from "./core/threeScene.js";
import * as fallback from "./radiationLite.js";
import { motionAllowed } from "./core/manager.js";
import { profile } from "../data/profile.js";

let instance;

function glowTexture() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.3, "rgba(255,255,255,0.5)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const shapeValue = (kind, x, y) => {
  if (kind === 0) return Math.sqrt(Math.max(0.001, 1 - y * y));
  if (kind === 1)
    return Math.max(
      0.05,
      Math.max(0, y) ** 1.6 + 0.08 * Math.sin(Math.acos(y) * 5) ** 2,
    );
  return Math.max(
    0.04,
    Math.max(0, x) ** 4 + 0.1 * Math.sin(Math.acos(x) * 5) ** 2,
  );
};

export function init(container, options = {}) {
  destroy();
  try {
    instance = threeScene(
      container,
      ({ scene, camera, renderer, lowPower, redraw }) => {
        camera.position.set(6, 3.5, 7);
        camera.lookAt(0, 0.3, 0);
        const add = THREE.AdditiveBlending;
        const glow = glowTexture();
        const group = new THREE.Group();
        scene.add(group);

        const geometry = new THREE.SphereGeometry(
          1,
          lowPower ? 44 : 80,
          lowPower ? 32 : 56,
        );
        const pos = geometry.attributes.position;
        const direction = new Float32Array(pos.array);
        const vertexColors = new Float32Array(pos.count * 3);
        geometry.setAttribute(
          "color",
          new THREE.BufferAttribute(vertexColors, 3),
        );
        const mesh = new THREE.Mesh(
          geometry,
          new THREE.MeshBasicMaterial({
            vertexColors: true,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.55,
            depthWrite: false,
          }),
        );
        group.add(mesh);
        const wire = new THREE.Mesh(
          geometry,
          new THREE.MeshBasicMaterial({
            vertexColors: true,
            wireframe: true,
            transparent: true,
            opacity: 0.45,
            blending: add,
            depthWrite: false,
          }),
        );
        group.add(wire);

        // antenna at the origin
        const antenna = new THREE.Mesh(
          new THREE.BoxGeometry(0.5, 0.04, 0.5),
          new THREE.MeshBasicMaterial({ color: 0xff3d3d }),
        );
        group.add(antenna);
        const core = new THREE.Sprite(
          new THREE.SpriteMaterial({
            map: glow,
            color: 0xff3d3d,
            blending: add,
            transparent: true,
            depthWrite: false,
          }),
        );
        core.scale.setScalar(1.2);
        group.add(core);

        // energy particles
        const COUNT = lowPower ? 360 : 1100;
        const pDir = new Float32Array(COUNT * 3),
          pPhase = new Float32Array(COUNT);
        for (let i = 0; i < COUNT; i++) {
          const u = Math.random() * 2 - 1,
            a = Math.random() * Math.PI * 2,
            s = Math.sqrt(1 - u * u);
          pDir.set([s * Math.cos(a), u, s * Math.sin(a)], i * 3);
          pPhase[i] = Math.random();
        }
        const pPos = new Float32Array(COUNT * 3),
          pCol = new Float32Array(COUNT * 3);
        const pGeo = new THREE.BufferGeometry();
        pGeo.setAttribute("position", new THREE.BufferAttribute(pPos, 3));
        pGeo.setAttribute("color", new THREE.BufferAttribute(pCol, 3));
        const particles = new THREE.Points(
          pGeo,
          new THREE.PointsMaterial({
            size: 0.13,
            map: glow,
            vertexColors: true,
            transparent: true,
            blending: add,
            depthWrite: false,
          }),
        );
        group.add(particles);

        // far-field shells (great-circle rings)
        const rings = [];
        const ringGeo = new THREE.TorusGeometry(1, 0.006, 4, 128);
        for (let i = 0; i < 4; i++) {
          const ring = new THREE.Mesh(
            ringGeo,
            new THREE.MeshBasicMaterial({
              color: 0x3dff9e,
              transparent: true,
              blending: add,
              depthWrite: false,
            }),
          );
          ring.rotation.x = Math.PI / 2;
          scene.add(ring);
          rings.push(ring);
        }

        for (let i = 0; i < 3; i++) {
          const axis = new THREE.Line(
            new THREE.BufferGeometry().setFromPoints([
              new THREE.Vector3(
                ...(i === 0
                  ? [-3.4, 0, 0]
                  : i === 1
                    ? [0, -3.4, 0]
                    : [0, 0, -3.4]),
              ),
              new THREE.Vector3(
                ...(i === 0
                  ? [3.4, 0, 0]
                  : i === 1
                    ? [0, 3.4, 0]
                    : [0, 0, 3.4]),
              ),
            ]),
            new THREE.LineDashedMaterial({
              color: 0x3dff9e,
              dashSize: 0.08,
              gapSize: 0.12,
              transparent: true,
              opacity: 0.35,
            }),
          );
          axis.computeLineDistances();
          scene.add(axis);
        }

        let drag = false,
          lastX = 0,
          lastY = 0,
          rx = 0.2,
          ry = 0;
        const canvas = renderer.domElement;
        const down = (e) => {
          drag = true;
          lastX = e.clientX;
          lastY = e.clientY;
          canvas.setPointerCapture(e.pointerId);
        };
        const move = (e) => {
          if (!drag) return;
          ry += (e.clientX - lastX) * 0.008;
          rx += (e.clientY - lastY) * 0.008;
          rx = Math.max(-1.2, Math.min(1.2, rx));
          lastX = e.clientX;
          lastY = e.clientY;
          redraw();
        };
        const up = () => (drag = false);
        canvas.addEventListener("pointerdown", down);
        canvas.addEventListener("pointermove", move);
        canvas.addEventListener("pointerup", up);
        canvas.addEventListener("pointercancel", up);
        const color = new THREE.Color();
        const label = container.parentElement.querySelector("[data-pattern]");
        const heat = (amplitude) => {
          const db = Math.max(
            -20,
            6 + 20 * Math.log10(Math.max(amplitude, 0.001)),
          );
          const n = (db + 20) / 26;
          color.setHSL((1 - n) * 0.62, 0.95, 0.35 + 0.25 * n);
          return n;
        };

        return {
          update(t, dt, still, c) {
            const phase = t * 0.09,
              shape = Math.floor(phase) % 3,
              mix = (1 - Math.cos((phase % 1) * Math.PI)) / 2;
            const amp = (x, y) =>
              shapeValue(shape, x, y) * (1 - mix) +
              shapeValue((shape + 1) % 3, x, y) * mix;
            const breathe = 1 + Math.sin(t * 1.4) * 0.03;
            for (let i = 0; i < pos.count; i++) {
              const x = direction[i * 3],
                y = direction[i * 3 + 1],
                z = direction[i * 3 + 2];
              const a = amp(x, y);
              const radius = 2.35 * (0.08 + 0.92 * a) * breathe;
              pos.setXYZ(i, x * radius, y * radius, z * radius);
              heat(a);
              vertexColors[i * 3] = color.r;
              vertexColors[i * 3 + 1] = color.g;
              vertexColors[i * 3 + 2] = color.b;
            }
            pos.needsUpdate = true;
            geometry.attributes.color.needsUpdate = true;
            geometry.computeBoundingSphere();

            // particles fly out along each direction, brightness ∝ gain
            const flow = still && !motionAllowed() ? 0.5 : t;
            for (let i = 0; i < COUNT; i++) {
              const x = pDir[i * 3],
                y = pDir[i * 3 + 1],
                z = pDir[i * 3 + 2];
              const a = amp(x, y);
              const life = (flow * (0.25 + 0.35 * a) + pPhase[i]) % 1;
              const r = 0.2 + life * (0.6 + 3.6 * a);
              pPos[i * 3] = x * r;
              pPos[i * 3 + 1] = y * r;
              pPos[i * 3 + 2] = z * r;
              const n = heat(a);
              const f = (1 - life) * (0.15 + 0.85 * n * n);
              pCol[i * 3] = color.r * f;
              pCol[i * 3 + 1] = color.g * f;
              pCol[i * 3 + 2] = color.b * f;
            }
            pGeo.attributes.position.needsUpdate = true;
            pGeo.attributes.color.needsUpdate = true;

            core.scale.setScalar(1 + 0.4 * (0.5 + 0.5 * Math.sin(t * 5)));
            rings.forEach((ring, i) => {
              const p = (t * 0.12 + i / rings.length) % 1;
              ring.scale.setScalar(0.6 + p * 4.2);
              ring.material.opacity = 0.5 * Math.sin(Math.PI * p);
              if (c.phosphor) ring.material.color.set(c.phosphor);
            });
            group.rotation.set(rx, ry + (motionAllowed() ? t * 0.12 : 0), 0);
            if (label)
              label.textContent =
                profile.diagrams.radiation.shapes[
                  mix < 0.5 ? shape : (shape + 1) % 3
                ];
          },
          dispose() {
            canvas.removeEventListener("pointerdown", down);
            canvas.removeEventListener("pointermove", move);
            canvas.removeEventListener("pointerup", up);
            canvas.removeEventListener("pointercancel", up);
            glow.dispose();
          },
        };
      },
      options,
    );
  } catch {
    container.querySelectorAll("canvas").forEach((c) => c.remove());
    fallback.init(container, options);
    instance = { destroy: () => fallback.destroy() };
  }
  return instance;
}

export function destroy() {
  instance?.destroy();
  instance = null;
}
